func (s UsageSnapshotServiceServer) apply(ctx context.Context, ref *rove.UsageSnapshotRef, doc *patchpb.Patch, by string) (*rove.UsageSnapshot, error) {
	plan := &ormpatch.Plan{Entity: usageSnapshotOrmEntity}
	if doc != nil {
		v, err := ormpatch.Compile(usageSnapshotOrmEntity, doc)
		if err != nil {
			if errors.Is(err, ormpatch.ErrUnsupported) {
				return nil, status.Errorf(codes.Unimplemented, "%s", err)
			}
			return nil, status.Errorf(codes.InvalidArgument, "%s", err)
		}
		plan = v
	}

	pred, mod, err := entpatch.Build(plan, usageSnapshotPatchColumns, s.Db.Dialect())
	if err != nil {
		if errors.Is(err, entpatch.ErrValue) {
			return nil, status.Errorf(codes.InvalidArgument, "%s", err)
		}
		return nil, status.Errorf(codes.Internal, "%s", err)
	}

	tx, err := ent1.JoinTx[*ent.Client, *ent.Tx](ctx, s.Db, true)
	if err != nil {
		return nil, err
	}
	defer tx.Close()

	st := s
	st.Db = tx.Db

	k, err := UsageSnapshotGetKey(ctx, st.Db, ref)
	if err != nil {
		return nil, err
	}
	at := &rove.UsageSnapshotRef{}
	at.SetId(k[:])
	p, err := s.narrow(ctx, usagesnapshot.IdEQ(k))
	if err != nil {
		return nil, err
	}

	if mod == nil {
		q := st.Db.UsageSnapshot.Query().Where(p)
		if pred != nil {
			q.Where(predicate.UsageSnapshot(pred))
		}
		if ok, err := q.Exist(ctx); err != nil {
			return nil, err
		} else if !ok {
			return nil, func() error {
				if ok, err := st.Db.UsageSnapshot.Query().Where(p).Exist(ctx); err != nil {
					return err
				} else if !ok {
					return status.Error(codes.NotFound, "UsageSnapshot not found")
				}
				return status.Error(codes.FailedPrecondition, "a test in the patch did not hold")
			}()
		}
	} else {
		q := st.Db.UsageSnapshot.Update().Where(p)
		if pred != nil {
			q.Where(predicate.UsageSnapshot(pred))
		}
		q.Modify(mod)
		if !plan.WritesTo(13) {
			q.SetDateUpdated(st.now())
		}
		if n, err := q.Save(ctx); err != nil {
			if err, ok := err.(*ent.ConstraintError); ok {
				if sqlgraph.IsUniqueConstraintError(err) {
					return nil, status.Error(codes.AlreadyExists, "UsageSnapshot already exists")
				}
				if sqlgraph.IsForeignKeyConstraintError(err) {
					return nil, status.Error(codes.NotFound, "UsageSnapshot: referenced entity not found")
				}
			}
			return nil, err
		} else if n == 0 {
			return nil, func() error {
				if ok, err := st.Db.UsageSnapshot.Query().Where(p).Exist(ctx); err != nil {
					return err
				} else if !ok {
					return status.Error(codes.NotFound, "UsageSnapshot not found")
				}
				return status.Error(codes.FailedPrecondition, "a test in the patch did not hold")
			}()
		}
	}

	if mod != nil {
		if err := record(ctx, s.Rec, st.Db, Change{
			By:    by,
			Key:   k,
			Patch: doc,
		}); err != nil {
			return nil, err
		}
	}

	out, err := st.Get(ctx, at.Pick())
	if err != nil {
		return nil, err
	}
	if err := tx.Commit(); err != nil {
		return nil, err
	}
	return out, nil
}

func (s UsageSnapshotServiceServer) Erase(ctx context.Context, req *rove.UsageSnapshotRef) (*rove.UsageSnapshotEraseResponse, error) {
	p, err := UsageSnapshotPick(req)
	if err != nil {
		return nil, err
	}
	p, err = s.narrow(ctx, p)
	if err != nil {
		return nil, err
	}

	tx, err := ent1.JoinTx[*ent.Client, *ent.Tx](ctx, s.Db, s.Rec != nil)
	if err != nil {
		return nil, err
	}
	defer tx.Close()

	st := s
	st.Db = tx.Db

	var k any
	if s.Rec != nil {
		v, err := st.Db.UsageSnapshot.Query().Where(p).OnlyId(ctx)
		if err != nil {
			if ent.IsNotFound(err) {
				return &rove.UsageSnapshotEraseResponse{}, nil
			}
			return nil, err
		}

		k = v
		p = usagesnapshot.And(p, usagesnapshot.IdEQ(v))
	}

	n, err := st.Db.UsageSnapshot.Delete().Where(p).Exec(ctx)
	if err != nil {
		return nil, err
	}
	if n > 0 {
		if err := record(ctx, s.Rec, st.Db, Change{
			By:  rove.UsageSnapshotService_Erase_FullMethodName,
			Key: k,
		}); err != nil {
			return nil, err
		}
	}
	if err := tx.Commit(); err != nil {
		return nil, err
	}
	res := &rove.UsageSnapshotEraseResponse{}
	res.SetErased(n > 0)

	return res, nil
}

func UsageSnapshotPick(req *rove.UsageSnapshotRef) (predicate.UsageSnapshot, error) {
	switch req.WhichKey() {
	case rove.UsageSnapshotRef_Id_case:
		if v, err := entuuid.FromBytes(req.GetId()); err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "id: %s", err)
		} else {
			return usagesnapshot.IdEQ(v), nil
		}
	case rove.UsageSnapshotRef_Day_case:
		k := req.GetDay()
		ps := make([]predicate.UsageSnapshot, 0, 2)
		if p, err := TenantPick(k.GetTenant()); err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "day.tenant: %s", err)
		} else {
			ps = append(ps, usagesnapshot.HasTenantWith(p))
		}
		ps = append(ps, usagesnapshot.DayEQ(k.GetDay()))
		return usagesnapshot.And(ps...), nil
	case rove.UsageSnapshotRef_Key_not_set_case:
		return nil, status.Errorf(codes.InvalidArgument, "key not set: UsageSnapshot")
	default:
		return nil, status.Errorf(codes.Unimplemented, "unknown type of key: %s", req.WhichKey())
	}
}
